  const grave=x.s[t].grave;const g=[...grave].reverse().find(v=>v.cardId===origin(u)&&v.owner===u.playedBy);if(g)x.s[t].grave=grave.filter(v=>v.uid!==g.uid);
  const fresh=spawn(x,u.cardId,t,u.playedBy,u.lane,0,true);fresh.rebornOnce=true;fresh.powerShift=Number(ruleFor(u).power||3)-power(x,t,fresh,0,true);syncGrave(x.s[t]);
