window.MythicPaintUniverseBanner=(banner,id)=>{
 const card=window.MythicCardData?.().find(c=>c.id===id),asset=window.MythicUniverseBanners[id]||(card?.hologram||card?.art?{atlas:card.hologram||card.art,format:'portrait'}:null);
 const main=banner.classList.contains('concept-story-banner');
 if(!asset){delete banner.dataset.customBanner;delete banner.dataset.bannerFormat;banner.querySelector('.universe-banner-art')?.remove();banner.querySelector('.universe-banner-image')?.remove();return;}
 banner.dataset.customBanner=id;banner.dataset.bannerFormat=asset.format||'wide';
 // Actual image dimensions reserve the banner area independently of legacy backgrounds.
 let media=main?banner.querySelector(':scope>.universe-banner-media'):banner;
 if(main&&!media){media=document.createElement('div');media.className='universe-banner-media';banner.prepend(media);const copy=banner.querySelector(':scope>.concept-story-banner-copy');if(copy)media.append(copy);}
 banner.querySelector('.universe-banner-art')?.remove();
 let node=media.querySelector(':scope>.universe-banner-image');if(!node){node=document.createElement('img');node.className='universe-banner-image';node.alt='';node.draggable=false;node.decoding='async';media.prepend(node);}
 const src=window.MythicSecurity?.assetUrl?.(asset.atlas)||asset.atlas;
 node.loading=main?'eager':'lazy';node.setAttribute('fetchpriority',main?'high':'low');node.width=asset.width||2048;node.height=asset.height||1024;node.style.objectPosition=asset.position||'center';
 node.onerror=()=>{if(node.dataset.fallback===id)return;node.dataset.fallback=id;const fallback=card?.hologram||card?.art;if(fallback&&fallback!==asset.atlas){node.src=window.MythicSecurity.assetUrl(fallback);node.classList.add('universe-image-fallback');}};
 if(node.dataset.source!==src){node.dataset.source=src;delete node.dataset.fallback;node.classList.remove('universe-image-fallback');node.src=src;}
};

