  window.addEventListener("mythic-profile-loaded",refreshArenaModeLocks);window.addEventListener("storage",event=>{if(event.key==="mythic-clash-tutorial-complete")refreshArenaModeLocks();});window.addEventListener("pageshow",refreshArenaModeLocks);document.querySelectorAll('[data-view="arena"]').forEach(button=>button.addEventListener("click",refreshArenaModeLocks));refreshArenaModeLocks();
  document.querySelectorAll(".arena-mode-card[data-mode]").forEach(b=>b.addEventListener("dblclick",()=>{b.click();if(b.dataset.mode==="bot"){showView("guardian");return;}if(b.dataset.mode==="friend"){showView("direct");$("#challenge-panel").hidden=false;return;}$("#arena-start").click();}));
  $("#arena-start").addEventListener("click",async()=>{refreshArenaModeLocks();if(window.MythicOnline?.isConnected?.()&&!window.MythicOnline.profileReady?.()){showToast("Aguarde seu perfil carregar.");return;}if(selectedArenaMode!=="bot"&&!isPvpUnlocked()){selectedArenaMode="bot";document.querySelector('[data-mode="bot"]').click();showToast("O PvP abre quando você alcançar o nível 2.");return;}if(selectedArenaMode==="bot"){showView("guardian");return;}if(selectedArenaMode==="tournament"){showView("tournaments");return;}if(deckTotal()<DECK_MIN||deckTotal()>DECK_MAX){showToast("Seu baralho precisa ter de 14 a 35 cartas.");showView("decks");return;}await window.MythicOnline?.saveDeckCounts?.({...deckCounts});if(selectedArenaMode==="friend"){$("#challenge-panel").hidden=false;return;}if(selectedArenaMode==="custom"){showView("custom");return;}if(selectedArenaMode==="normal"||selectedArenaMode==="ranked"){window.MythicOnline?.openQueueLobby?.(selectedArenaMode);showView("queue");return;}window.MythicOnline?.startQueue(selectedArenaMode);});
  let surrenderDialog=null;
  function requestSurrender(){
    if(!duel)return;if(duel.finished){showCompletedReport();return;}if(duel.pendingEffect&&!duel.practice){showToast("Conclua a escolha da habilidade antes de desistir.");return;}
    if(surrenderDialog?.open){surrenderDialog.focus();return;}
    const target=duel,matchId=target.onlineMatchId,dialog=document.createElement('dialog');surrenderDialog=dialog;
    const sameMatch=()=>Boolean(duel&&(target.online?duel.onlineMatchId===matchId:duel===target));
    dialog.className='surrender-dialog';dialog.setAttribute('aria-labelledby','surrender-title');dialog.setAttribute('aria-describedby','surrender-description');
    const title=document.createElement('h2');title.id='surrender-title';title.textContent=target.practice?'Encerrar este teste?':'Desistir da partida?';
    const description=document.createElement('p');description.id='surrender-description';description.textContent=target.practice?'O teste será encerrado e você poderá consultar o resumo.':target.teamSize===2?'Ao confirmar, a partida termina com derrota para sua dupla e vitória para a dupla adversária.':'Ao confirmar, a partida termina com sua derrota e a vitória do adversário.';
    const status=document.createElement('p');status.className='surrender-error';status.setAttribute('role','alert');
    const actions=document.createElement('div');actions.className='surrender-actions';
    const cancel=document.createElement('button');cancel.type='button';cancel.className='button button-secondary';cancel.textContent=target.practice?'Continuar teste':'Continuar jogando';cancel.autofocus=true;
    const confirm=document.createElement('button');confirm.type='button';confirm.className='button button-primary surrender-confirm';confirm.textContent=target.practice?'Encerrar teste':'Sim, desistir';
    let sending=false;const close=()=>{dialog.close();dialog.remove();if(surrenderDialog===dialog)surrenderDialog=null;};
    cancel.onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();if(!sending)close();});
    confirm.onclick=async()=>{
      if(sending)return;if(!sameMatch()){close();return;}if(duel.finished){close();showCompletedReport();return;}
      sending=true;cancel.disabled=true;confirm.disabled=true;confirm.textContent='Encerrando…';status.textContent='';dialog.setAttribute('aria-busy','true');
      try{
        if(duel.practice){close();exitPractice();return;}
        if(duel.online){
          if(duel.guardianCampaign)await window.MythicGuardianCampaign.surrender(matchId);
          else await window.MythicOnline.surrenderMatch(matchId);
          if(sameMatch()&&!duel.finished)throw Error('Não foi possível confirmar o resultado. Tente novamente; a solicitação não será duplicada.');
          close();return;
        }
        const player=roundScore(duel.player),enemy=roundScore(duel.enemy);
        duel.roundScores=duel.roundScores||[];if(!duel.roundScores.some(r=>r.round===duel.round))duel.roundScores.push({round:duel.round,player,enemy,in_progress:true});
        duel.lastRoundPoints={player,enemy};duel.finished=true;duel.finishedAt=Date.now();duel.surrendered=true;duel.serverOutcome='defeat';duel.winner='Você desistiu da partida.';
        duel.pendingEffect=null;duel.effectQueue=[];duel.eclipseReveal=null;duel.resultAnimationShown=false;duel.onlineResultShown=false;
        log('Você desistiu da partida. Vitória do Guardião.');close();window.MythicAbilitiesUI?.close();window.MythicCombatFX?.clear();window.MythicEclipseUI?.close();saveDuel();renderDuel();
      }catch(error){status.textContent=error.message||'Não foi possível confirmar a desistência. Tente novamente.';}
      finally{sending=false;cancel.disabled=false;confirm.disabled=false;confirm.textContent=target.practice?'Encerrar teste':'Sim, desistir';dialog.removeAttribute('aria-busy');}
    };
    actions.append(cancel,confirm);dialog.append(title,description,status,actions);document.body.append(dialog);dialog.showModal();
  }
  $("#leave-duel").addEventListener("click",requestSurrender);
  window.addEventListener('mythic-account-signed-out',()=>{surrenderDialog?.close();surrenderDialog?.remove();surrenderDialog=null;});
