  function cardArt(card,small=false){if(card.art)return `<img loading="lazy" decoding="async" src="${escapeHTML(safeUrl(card.art))}" alt="Carta ${escapeHTML(card.name)}">`;return `<span class="${small?"generic-art":"lore-story-glyph"}" style="--card-glow:${card.glow}">${card.symbol}</span>`;}
  function rankEmblemForRating(rating){const value=Number(rating)||1000,name=value<1100?"aprendiz-de-heroi":value<1250?"escudeiro":value<1450?"heroi":value<1700?"lenda":value<2000?"semideus":value<2400?"deus":"convergente";return `assets/identity-v2/${name}.webp`;}
  function showBattleIntro({playerName="Você",playerIcon="default",playerRating=1000,enemyName="Oponente",enemyIcon="default",enemyRating=1000,after=null}={}){const panel=$("#battle-intro"),renderAvatar=(icon,name)=>{const src=window.MythicOnline?.avatarAsset?.(icon);return src?`<img src="${escapeHTML(src)}" alt="Ícone de ${escapeHTML(name)}">`:`<span>${escapeHTML(String(name).trim().slice(0,1).toUpperCase()||"?")}</span>`;};$("#intro-player-icon").innerHTML=renderAvatar(playerIcon,playerName);$("#intro-enemy-icon").innerHTML=renderAvatar(enemyIcon,enemyName);$("#intro-player-rank").src=rankEmblemForRating(playerRating);$("#intro-enemy-rank").src=rankEmblemForRating(enemyRating);$("#intro-player-rank").alt="Rank do invocador";$("#intro-enemy-rank").alt="Rank do oponente";$("#intro-player-name").textContent=playerName;$("#intro-enemy-name").textContent=enemyName;panel.hidden=false;panel.setAttribute("aria-hidden","false");clearTimeout(panel._dismissTimer);panel._dismissTimer=setTimeout(()=>{panel.hidden=true;panel.setAttribute("aria-hidden","true");if(typeof after==="function")after();},2400);}
  function renderCollection(){
    const collectionCards=cards.filter(card=>ownedCopies(card)>0);
    const factionSelect=$("#faction-filter"), selectedFaction=factionSelect.value||"all";
    const factions=[...new Set(collectionCards.map(card=>card.faction))].sort();
    factionSelect.innerHTML='<option value="all">Todas as facções</option>'+factions.map(faction=>`<option value="${escapeHTML(faction)}">${escapeHTML(faction)}</option>`).join("");factionSelect.value=factions.includes(selectedFaction)?selectedFaction:"all";
    const counts={all:collectionCards.length};collectionCards.forEach(card=>counts[card.type]=(counts[card.type]||0)+1);
    $("#filter-tabs").innerHTML=filters.map(([value,label])=>`<button class="filter-tab ${activeFilter===value?"active":""}" data-filter="${value}">${label}${value==="all"?` <small>${collectionCards.length}</small>`:""}</button>`).join("");
    const query=$("#card-search").value.trim().toLocaleLowerCase("pt-BR"), faction=factionSelect.value;
    const visible=collectionCards.filter(card=>(activeFilter==="all"||card.type===activeFilter)&&(faction==="all"||card.faction===faction)&&(!query||`${card.name} ${card.type} ${card.faction}`.toLocaleLowerCase("pt-BR").includes(query)));
    $("#collection-grid").innerHTML=visible.map(card=>`<article class="collection-card" style="--card-glow:${card.glow}"><button class="collection-art-button" data-card="${card.id}" aria-label="Ver detalhes de ${escapeHTML(card.name)}">${cardArt(card,true)}</button><div class="collection-card-info"><div><span class="card-kind">${(card.subtype||card.type).toLocaleUpperCase("pt-BR")} · ${escapeHTML(card.faction.toLocaleUpperCase("pt-BR"))}${card.specialOnly?(card.kind==="event"?" · RESULTADO DO ECLIPSE":" · TRANSFORMAÇÃO"):card.previewOnly?" · EM PREPARAÇÃO":""}</span><h2>${escapeHTML(card.name)}</h2></div><span class="power-chip">${card.power||"—"}<small>${card.power?"PODER":"ESPECIAL"}</small></span></div><p class="collection-card-rule">${escapeHTML(card.ability)}</p><button class="card-detail-button" data-card="${card.id}">Ver carta, habilidade e história</button></article>`).join("");
    $("#empty-search").hidden=visible.length>0;$("#nav-card-count").textContent=String(collectionCards.length).padStart(2,"0");
  }
  $("#filter-tabs").addEventListener("click",event=>{const button=event.target.closest("[data-filter]");if(!button)return;activeFilter=button.dataset.filter;renderCollection();});
  $("#card-search").addEventListener("input",renderCollection);$("#faction-filter").addEventListener("change",renderCollection);
  function fullCardPreview(card){if(card.art)return `<img src="${escapeHTML(safeUrl(card.art))}" alt="Carta completa: ${escapeHTML(card.name)}">`;return `<article class="full-card-preview" style="--card-glow:${card.glow}"><header>MYTHIC CLASH</header><div class="full-card-symbol">${card.symbol}</div><h3>${escapeHTML(card.name)}</h3><small>${escapeHTML(card.type.toLocaleUpperCase("pt-BR"))} · ${escapeHTML(card.faction.toLocaleUpperCase("pt-BR"))}</small><p><b>${escapeHTML(card.abilityTitle||"Habilidade")}</b><br>${escapeHTML(card.ability)}</p><footer><span>${card.power?`${card.power} PODER`:card.type.toLocaleUpperCase("pt-BR")}</span></footer></article>`;}
  function openUnderworldGallery(sideKey){if(!duel)return;underworldCardIds=duel[sideKey].underworld.filter(id=>cardById[id]);if(!underworldCardIds.length){showToast("Não há cartas no Submundo.");return;}underworldFocusIndex=0;openCardDetail(underworldCardIds[0],null,false,true);}
  function closeUnderworldGallery(){$("#underworld-gallery").hidden=true;}
