  document.addEventListener("keydown",event=>{if(event.key==="Escape")closeUnderworldGallery();});
  function renderExpandedHandFan(selectedIndex,cardIds=duel?.player.hand||[]){
    const fan=$("#expanded-hand-fan");
    if(!duel||!Number.isInteger(selectedIndex)){fan.innerHTML="";fan.hidden=true;return;}
    fan.innerHTML=cardIds.map((id,index)=>{
      if(index===selectedIndex)return "";
      const other=cardById[id],offset=index-selectedIndex;
      return `<button type="button" class="fan-card" data-detail-index="${index}" aria-label="Ampliar ${escapeHTML(other.name)}" style="--fan-x:${offset*174}px;--fan-y:${Math.abs(offset)*16}px;--fan-rotate:${offset*13}deg;--fan-z:${10-Math.abs(offset)};--card-glow:${other.glow}">${fullCardPreview(other)}</button>`;
    }).join("");
    fan.hidden=cardIds.length<2;
  }
  function openCardDetail(id,handIndex=null,fromField=false,fromUnderworld=false,fromDeck=false){const card=cardById[id];if(!card)return;detailHandIndex=Number.isInteger(handIndex)?handIndex:null;$("#card-detail-modal").classList.toggle("collection-card-expanded",activeView==="collection");$("#card-detail-modal").classList.toggle("shop-card-expanded",activeView==="store");const art=$("#card-detail-art"),isHandCard=detailHandIndex!==null,underworldIndex=fromUnderworld?underworldCardIds.indexOf(id):-1;if(fromUnderworld&&underworldIndex>=0)underworldFocusIndex=underworldIndex;$("#card-detail-modal").classList.toggle("duel-card-expanded",isHandCard||fromUnderworld);$("#card-detail-modal").classList.toggle("underworld-card-expanded",fromUnderworld);$("#card-detail-modal").classList.toggle("field-card-expanded",Boolean(fromField));$("#card-detail-modal").classList.toggle("deck-card-expanded",fromDeck);renderExpandedHandFan(fromUnderworld?underworldFocusIndex:detailHandIndex,fromUnderworld?underworldCardIds:undefined);art.style.setProperty("--card-glow",card.glow);art.innerHTML=fullCardPreview(card);$("#card-detail-kind").textContent=card.type.toLocaleUpperCase("pt-BR");$("#card-detail-title").textContent=card.name;$("#card-detail-faction").textContent=`Facção: ${card.faction}`;$("#card-detail-power").textContent=card.power||"—";$("#card-detail-ability").textContent=card.ability+(card.previewOnly?" Esta carta está em preparação e ainda não pode ser usada nas partidas.":"");$("#card-detail-story").innerHTML=card.story.map(paragraph=>`<p>${escapeHTML(paragraph)}</p>`).join("");const canBrowse=isHandCard||(fromUnderworld&&underworldCardIds.length>1);$("#card-detail-prev").hidden=!canBrowse;$("#card-detail-next").hidden=!canBrowse;$("#card-detail-count").hidden=!canBrowse;$("#card-detail-action").hidden=!isHandCard;$("#detail-play-hint").hidden=!isHandCard;if(isHandCard){$("#card-detail-count").textContent=`${detailHandIndex+1} / ${duel.player.hand.length}`;updateDetailPlayState(card);}else if(fromUnderworld){$("#card-detail-count").textContent=`${underworldFocusIndex+1} / ${underworldCardIds.length}`;}$("#card-detail-backdrop").hidden=false;$("#card-detail-close").focus();}
  document.addEventListener("click",event=>{if(event.defaultPrevented||event.target.closest("#deck-builder,.db-zoom,.db-exit"))return;const button=event.target.closest("[data-card]");if(button)openCardDetail(button.dataset.card,null,false,false,button.classList.contains("deck-card-thumb"));});
  function cardZoneKey(card){return card.kind==="location"?"local":card.kind==="terrain"?"terrain":["event","climate","weather"].includes(card.kind)?"climate":null;}
  function playBlockReason(side,card,laneIndex=null,zoneKey=null){if(window.MythicAvailability?.isDisabled(card.id))return "Esta carta está temporariamente indisponível.";if(!duel||duel.finished)return "Este duelo já terminou.";if(window.MythicCombatFX?.isBusy()||window.MythicEclipseUI?.isRevealing())return "Aguarde a animação da arena.";if(duel.pendingEffect)return "Resolva a habilidade pendente para concluir a jogada.";if(side.passed)return "Você já passou neste Round e não pode jogar mais cartas.";if(duel.owner!=="player")return "Aguarde o fim do turno do oponente.";if(side.playedThisTurn)return "Você já jogou uma carta neste turno.";if(card.specialOnly)return "Esta carta especial não pode ser jogada da mão.";if(card.kind==="equipment"&&!side.field.some(unit=>window.MythicEquipmentRules.canTarget(card,unit,cardById)))return "Não há um aliado compatível em campo. "+card.ability;if(card.kind==="relic"&&!side.field.length)return "Jogue um personagem antes de usar esta relíquia.";const requiredZone=cardZoneKey(card);if(requiredZone&&zoneKey&&zoneKey!==requiredZone)return "Esta carta deve ir para o espaço de "+({local:"Local",terrain:"Terreno",climate:"Clima"}[requiredZone])+".";if(requiredZone&&!window.MythicZoneRules.canReplace(card,cardById[duel.sharedZones[requiredZone]]))return "Somente Clima/Evento pode substituir o Clima/Evento ativo.";return "";}
  function updateDetailPlayState(card){const reason=playBlockReason(duel.player,card),button=$("#card-detail-action");button.disabled=Boolean(reason);$("#detail-play-hint").textContent=reason||"Arraste a carta para o campo ou jogue por este botão.";}
  function animateCardPlacement(id,source){if(!source)return;const target=document.querySelector(`.battle-mini-card[data-card-id="${id}"],.battle-zone[data-zone-card="${id}"]`)||document.querySelector("#shared-zones");if(!target)return;const a=source.rect||source.getBoundingClientRect(),b=target.getBoundingClientRect(),flight=document.createElement("div");flight.className="card-placement-flight";flight.innerHTML=source.html||source.innerHTML;flight.style.left=a.left+"px";flight.style.top=a.top+"px";flight.style.width=a.width+"px";flight.style.height=a.height+"px";document.body.append(flight);const dx=b.left-a.left,dy=b.top-a.top;flight.animate([{transform:"translate(0,0) scale(1) rotate(0)",opacity:1},{transform:`translate(${dx}px,${dy}px) scale(.72) rotate(-5deg)`,opacity:.15}],{duration:650,easing:"cubic-bezier(.2,.75,.25,1)"}).onfinish=()=>flight.remove();if(cardById[id]?.kind==="unit")return;target.classList.remove("card-arrival");requestAnimationFrame(()=>target.classList.add("card-arrival"));const card=cardById[id],effect=document.createElement("span");effect.className=`ability-arrival-effect ${id==="medusa"?"medusa-arrival":""}`;effect.textContent=id==="medusa"?"❄ PETRIFICAÇÃO":card?.kind==="unit"?"✦ ENTRADA EM CAMPO":"✧ HABILIDADE ATIVADA";target.append(effect);setTimeout(()=>{target.classList.remove("card-arrival");effect.remove();},1450);}
  function tryPlayHandCard(index,laneIndex=null,zoneKey=null,targetIndex=null){if(window.MythicCombatFX?.isBusy())return false;if(!duel||index<0||index>=duel.player.hand.length)return false;const id=duel.player.hand[index],card=cardById[id],origin=handElement.querySelector(`[data-hand-index="${index}"]`),source=origin?{rect:origin.getBoundingClientRect(),html:origin.innerHTML}:null;zoneKey=zoneKey||cardZoneKey(card);if(card.kind==="unit"&&!Number.isInteger(laneIndex))laneIndex=duel.player.field.length%3;const reason=playBlockReason(duel.player,card,laneIndex,zoneKey);if(reason){showToast(reason);return false;}detailHandIndex=null;$("#card-detail-backdrop").hidden=true;handFocusIndex=Math.min(index,duel.player.hand.length-1);if(duel.online){window.MythicOnline?.submitAction({type:"play",card_id:id,lane:laneIndex,zone_key:zoneKey,target_index:targetIndex});return true;}if(!playCard(duel.player,id,false,laneIndex,targetIndex))return false;if(duel.practice){practiceReady();renderDuel();requestAnimationFrame(()=>animateCardPlacement(id,source));return true;}if(duel.pendingEffect){renderDuel();return true;}if(duel.player.passed)log("Você ficou sem cartas e passou automaticamente.");endAbilityTurn("player");duel.owner="enemy";renderDuel();requestAnimationFrame(()=>animateCardPlacement(id,source));scheduleEnemyTurn(2000);return true;}
  function moveHandDetail(step){if(detailHandIndex===null||!duel?.player.hand.length)return;detailHandIndex=(detailHandIndex+step+duel.player.hand.length)%duel.player.hand.length;handFocusIndex=detailHandIndex;renderDuel();openCardDetail(duel.player.hand[detailHandIndex],detailHandIndex);}
  function closeCardDetail(){$("#card-detail-backdrop").hidden=true;detailHandIndex=null;underworldCardIds=[];$("#card-detail-modal").classList.remove("field-card-expanded","underworld-card-expanded","duel-card-expanded","deck-card-expanded","collection-card-expanded","shop-card-expanded");}
  $("#card-detail-close").addEventListener("click",closeCardDetail);$("#card-detail-backdrop").addEventListener("click",event=>{if(event.target.id==="card-detail-backdrop")closeCardDetail();});$("#card-detail-modal").addEventListener("click",event=>{if(!$("#card-detail-modal").classList.contains("duel-card-expanded"))return;if(Date.now()<detailSuppressClickUntil){event.preventDefault();return;}if(event.target.closest(".card-detail-art,.detail-swipe,.modal-close,.detail-play-button,.fan-card"))return;closeCardDetail();});document.addEventListener("keydown",event=>{if(event.key==="Escape")closeCardDetail();});
  function moveUnderworldDetail(step){if(!underworldCardIds.length)return;underworldFocusIndex=(underworldFocusIndex+step+underworldCardIds.length)%underworldCardIds.length;openCardDetail(underworldCardIds[underworldFocusIndex],null,false,true);}
  $("#card-detail-prev").addEventListener("click",()=>$("#card-detail-modal").classList.contains("underworld-card-expanded")?moveUnderworldDetail(-1):moveHandDetail(-1));$("#card-detail-next").addEventListener("click",()=>$("#card-detail-modal").classList.contains("underworld-card-expanded")?moveUnderworldDetail(1):moveHandDetail(1));
  $("#card-detail-action").addEventListener("click",()=>{if(detailHandIndex!==null)tryPlayHandCard(detailHandIndex);});
  let detailSuppressClickUntil=0;
  const detailModal=$("#card-detail-modal");
  function browseDetail(step){if(detailModal.classList.contains("underworld-card-expanded"))moveUnderworldDetail(step);else moveHandDetail(step);}
  detailModal.addEventListener("click",event=>{const card=event.target.closest("[data-detail-index]");if(!card)return;event.preventDefault();event.stopPropagation();if(Date.now()<detailSuppressClickUntil)return;const index=Number(card.dataset.detailIndex);if(detailModal.classList.contains("underworld-card-expanded"))moveUnderworldDetail(index-underworldFocusIndex);else if(detailHandIndex!==null)moveHandDetail(index-detailHandIndex);});
  detailModal.addEventListener("pointerdown",event=>{if(event.button!==0||event.target.closest(".modal-close,.detail-swipe,.detail-play-button"))return;if(detailHandIndex===null&&!detailModal.classList.contains("underworld-card-expanded"))return;detailGestureStart={x:event.clientX,y:event.clientY,id:event.pointerId};});
  detailModal.addEventListener("pointermove",event=>{const g=detailGestureStart;if(g&&g.id===event.pointerId&&Math.abs(event.clientX-g.x)>12&&Math.abs(event.clientX-g.x)>Math.abs(event.clientY-g.y))detailModal.setPointerCapture(event.pointerId);});
  detailModal.addEventListener("pointerup",event=>{const gesture=detailGestureStart;if(!gesture||gesture.id!==event.pointerId)return;detailGestureStart=null;const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;if(detailModal.hasPointerCapture(event.pointerId))detailModal.releasePointerCapture(event.pointerId);if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2){detailSuppressClickUntil=Date.now()+400;event.preventDefault();browseDetail(dx<0?1:-1);}else{const card=document.elementFromPoint(event.clientX,event.clientY)?.closest("[data-detail-index]");if(card){detailSuppressClickUntil=Date.now()+400;const index=Number(card.dataset.detailIndex);if(detailModal.classList.contains("underworld-card-expanded"))moveUnderworldDetail(index-underworldFocusIndex);else if(detailHandIndex!==null)moveHandDetail(index-detailHandIndex);}}});
  detailModal.addEventListener("pointercancel",()=>{detailGestureStart=null;});
  document.addEventListener("keydown",event=>{if($("#card-detail-backdrop").hidden||!detailModal.classList.contains("duel-card-expanded")||event.target.matches("input,textarea,select"))return;if(event.key==="ArrowLeft"||event.key==="ArrowRight"){event.preventDefault();browseDetail(event.key==="ArrowLeft"?-1:1);}});
  function isUniverseCharacter(card){return card?.kind==="unit"&&!card.specialOnly;}
