  function openStory(cardId){const card=cardById[cardId];if(!isUniverseCharacter(card))return;const modal=$("#lore-detail-backdrop"),art=$("#lore-detail-art"),theme=$("#lore-theme-audio"),source=$("#lore-theme-source"),comic=$("#lore-comic-link");art.innerHTML=cardArt(card,false);$("#lore-detail-kicker").textContent=`${escapeHTML(card.type.toLocaleUpperCase("pt-BR"))} · ${escapeHTML(card.faction.toLocaleUpperCase("pt-BR"))}`;$("#lore-detail-title").textContent=card.name;$("#lore-detail-power").textContent=card.power?`${card.power} poder`:`${card.type}`;$("#lore-detail-ability").textContent=card.ability;$("#lore-detail-story").innerHTML=card.story.map(paragraph=>`<p>${escapeHTML(paragraph)}</p>`).join("");comic.hidden=!card.comicUrl;if(card.comicUrl)comic.href=card.comicUrl;theme.pause();theme.removeAttribute("src");source.hidden=true;$("#lore-theme-placeholder").hidden=Boolean(card.themeUrl);if(card.themeUrl){theme.src=card.themeUrl;source.hidden=false;theme.currentTime=0;theme.play().catch(()=>{});}modal.hidden=false;if(!modal.closest("#view-lore"))document.body.classList.add("lore-detail-open");$("#lore-detail-close").focus();}
