    if(duel.round<3&&Math.max(wins.player,wins.enemy)<2){duel.round+=1;log("Começa o Round "+duel.round+". Placar de Rounds: "+wins.player+" a "+wins.enemy+".");renderDuel();setTimeout(startNextRound,2000);return;}
    const winner=wins.player===wins.enemy?null:wins.player>wins.enemy?"player":"enemy";
