  function continueAfterEnemyTurn(){if(!duel||duel.finished)return;endAbilityTurn("enemy");if(duel.player.passed&&duel.enemy.passed){finishRound();return;}if(duel.player.passed){endAbilityTurn("player");duel.owner="enemy";renderDuel();scheduleEnemyTurn(2000);return;}startTurn(duel.player,"player");if(duel.player.skipNextTurn){duel.player.skipNextTurn=false;log("Você foi petrificado pela Medusa e perdeu este turno.");endAbilityTurn("player");duel.owner="enemy";renderDuel();scheduleEnemyTurn(2000);return;}if(duel.player.passed){log("Você não tem mais cartas e passou automaticamente.");endAbilityTurn("player");duel.owner="enemy";renderDuel();scheduleEnemyTurn(2000);return;}log("Seu turno começou. Jogue uma carta ou passe a vez.");renderDuel();}
  function scheduleEnemyTurn(delay){if(duel?.practice)return;const match=duel;setTimeout(()=>{if(duel===match)enemyTurn();},delay);}
  function resolveEnemyChoices(done){const match=duel;if(!match||match.finished)return;if(match.pendingEffect?.actor!=='enemy'){if(!match.pendingEffect)done();return;}setTimeout(()=>{if(duel!==match||match.finished)return;try{const p=duel.pendingEffect;if(!p||p.actor!=='enemy'){done();return;}const ctx=abilitiesContext();window.MythicAbilities.action(ctx,'enemy',{type:'resolve_effect',choice_id:p.id,choice_value:p.options[0].value});flushAbilities(ctx);renderDuel();resolveEnemyChoices(done);}catch(error){showToast(error.message);}},1000);}
