  function enemyTurn(){if(!duel||duel.finished||duel.practice||duel.owner!=="enemy")return;if(window.MythicEclipseUI.isRevealing()||window.MythicCombatFX?.isBusy()){scheduleEnemyTurn(120);return;}if(duel.enemy.passed){continueAfterEnemyTurn();return;}startTurn(duel.enemy,"enemy");if(duel.pendingEffect){renderDuel();resolveEnemyChoices(()=>{if(!duel)return;delete duel.abilityPhase;completeTurnDraw(duel.enemy,'enemy');enemyPlay();});return;}enemyPlay();}
  function renderHand(player){
    if(!player.hand.length)return '<p class="battle-empty">Sem cartas na mão. Aguarde uma compra ou passe a vez.</p>';
    handFocusIndex=Math.min(handFocusIndex,player.hand.length-1);
    return player.hand.map((id,index)=>{
      const card=cardById[id];
      const art=card.art?`<img class="hand-full-art" src="${escapeHTML(safeUrl(card.art))}" alt="Carta completa: ${escapeHTML(card.name)}">`:card.symbol;
      const contents=card.art?art:`<span class="hand-glyph">${art}</span><b>${escapeHTML(card.name)}</b><small>${escapeHTML(card.ability)}</small><span class="hand-power">${card.power?`${card.power} poder`:card.type}</span>`;
      return `<button class="hand-card ${index===handFocusIndex?"selected":""} ${card.art?"has-full-art":""}" draggable="false" data-hand-index="${index}" data-card-id="${card.id}" style="--card-glow:${card.glow}" aria-pressed="${index===handFocusIndex}" aria-label="Ampliar ${escapeHTML(card.name)}">${contents}</button>`;
    }).join("");
  }
  function renderZones(){return [["local","LOCAL","⌂"],["terrain","TERRENO","▱"],["climate","CLIMA","◌"]].map(([key,label,glyph])=>{const cardId=key==="climate"?window.MythicEclipseUI.displayClimate(duel):duel.sharedZones&&duel.sharedZones[key],card=cardId&&cardById[cardId];if(!card)return '<div class="battle-zone" data-drop-zone="'+key+'" aria-label="'+label+': vazio. Solte aqui a carta correspondente"><small>'+label+'</small><span class="zone-glyph">'+glyph+'</span><b>Vazio</b></div>';const art=card.art?'<img src="'+card.art+'" alt="">':'<span>'+escapeHTML(card.symbol)+'</span>';return '<div class="battle-zone occupied" role="button" tabindex="0" data-zone-card="'+cardId+'" aria-label="Ampliar carta '+escapeHTML(card.name)+' em '+label+'"><article class="zone-card-mini" style="--card-glow:'+card.glow+'" title="'+escapeHTML(card.name)+'"><header><span>'+escapeHTML(card.faction.toLocaleUpperCase("pt-BR"))+'</span><b>'+escapeHTML(card.symbol)+'</b></header><div class="zone-card-mini-art">'+art+'</div><strong>'+escapeHTML(card.name)+'</strong><small>'+escapeHTML(card.type.toLocaleUpperCase("pt-BR"))+'</small></article></div>';}).join("");}
  $("#shared-zones").addEventListener("click",event=>{const slot=event.target.closest("[data-zone-card]");if(slot)openCardDetail(slot.dataset.zoneCard,null,true);});
  $("#shared-zones").addEventListener("keydown",event=>{if(event.key!=="Enter"&&event.key!==" ")return;const slot=event.target.closest("[data-zone-card]");if(!slot)return;event.preventDefault();openCardDetail(slot.dataset.zoneCard,null,true);});
  function renderField(side){
    const holo=(card,uid="")=>card.hologram?`<span class="battle-hologram"${uid?` data-unit-uid="${escapeHTML(uid)}"`:""} aria-hidden="true"><img src="${escapeHTML(safeUrl(card.hologram))}" alt="" draggable="false"><i class="battle-hologram-scan" style="--hologram-mask:url('${escapeHTML(safeUrl(card.hologram))}')"></i></span>`:"";
    const mini=(unit,index=0)=>{const original=cardById[unit.cardId],card=cardById[unit.copiedFrom]||original,power=currentPower(side,unit);return `<article tabindex="0" class="battle-mini-card ${card.art?"has-card-art ":""}${card.hologram?"has-hologram":""}" style="--stack-index:${index}" data-unit-uid="${escapeHTML(unit.uid)}" data-field-index="${side.field.indexOf(unit)}" data-card-id="${card.id}" title="${escapeHTML(card.name)} · ${power} poder">${card.art?`<img src="${escapeHTML(safeUrl(card.art))}" alt="${escapeHTML(card.name)}">`:`<span class="mini-glyph">${escapeHTML(card.symbol)}</span>`}<span class="mini-card-meta"><b>${escapeHTML(card.name)}</b><strong>${power}</strong></span>${holo(card)}${unit.copiedFrom?`<span class="copied-identity">Loki · ${escapeHTML(card.abilityTitle||"habilidade copiada")}</span>`:""}</article>`;};
    return (side===duel.enemy?[2,1,0]:[0,1,2]).map(lane=>{const units=side.field.filter(u=>u.lane===lane),companions=units.filter(u=>{const c=cardById[u.cardId];return c.type==="Companheiro"||c.subtype==="Companheiro";}),others=units.filter(u=>!companions.includes(u));let pile="";if(companions.length>1){pile=`<div class="companion-stack" style="--formation-cols:${Math.min(6,companions.length)}">${companions.map(mini).join("")}<div class="companion-formation">${companions.map(u=>holo(cardById[u.cardId],u.uid)).join("")}</div><button type="button" class="stack-expand" aria-label="Ver ${companions.length} companheiros da fileira" aria-expanded="false">×${companions.length}</button></div>`;}else pile=companions.map(mini).join("");return `<div class="battle-lane" data-lane-index="${lane}" aria-label="Linha ${lane+1}">${pile}${others.map(mini).join("")}</div>`;}).join("");
  }
  document.addEventListener("click",event=>{const b=event.target.closest(".stack-expand");if(!b)return;event.stopPropagation();const open=b.parentElement.classList.toggle("expanded");b.setAttribute("aria-expanded",String(open));queueHologramSync();});
  function renderEnemyHand(hand){return hand.map((_,index)=>'<span class="enemy-hand-back" style="--back-x:'+((index-(hand.length-1)/2)*27)+'px;--back-angle:'+((index-(hand.length-1)/2)*4)+'deg;--back-z:'+index+'" aria-hidden="true"></span>').join("");}
  function renderUnderworldPile(side,pileId,stackId,countId,label){
    const cards=side.underworld;
    $(countId).textContent=cards.length;
    $(pileId).setAttribute("aria-label",label+": "+cards.length+" cartas");
    $(stackId).innerHTML=cards.slice(-5).map((id,index,array)=>{
      const card=cardById[id],middle=(array.length-1)/2,left=(index-middle)*9,angle=(index-middle)*7;
      const face=card.art?'<img src="'+card.art+'" alt="">':'<span class="underworld-glyph">'+escapeHTML(card.symbol)+'</span>';
      return '<span class="underworld-card" title="'+escapeHTML(card.name)+'" style="left:calc(50% + '+left+'px);z-index:'+index+';transform:translateX(-50%) rotate('+angle+'deg)">'+face+'<b>'+escapeHTML(card.name)+'</b></span>';
    }).join("")||'<span class="underworld-empty-mark">✦</span>';
  }
  function syncBattleHolograms(){
    document.getElementById("battle-hologram-layer")?.remove();
    if(activeView!=="duel")return;
    document.querySelectorAll('#shared-zones .zone-card-mini').forEach(card=>{card.style.setProperty('--zone-card-width',card.clientWidth+'px');card.style.setProperty('--zone-card-height',card.clientHeight+'px');});
    const battleStyle=getComputedStyle($('#view-duel')),memberWidth=parseFloat(battleStyle.getPropertyValue('--battle-hologram-width'))||89.0625,memberHeight=parseFloat(battleStyle.getPropertyValue('--battle-hologram-height'))||106.25;
    const step=memberWidth*.43,rowStep=memberHeight*.42;
    document.querySelectorAll('#view-duel .battle-lane').forEach(lane=>lane.style.setProperty('--formation-headroom','0px'));
    document.querySelectorAll("#view-duel .companion-stack").forEach(pile=>{
      const cards=[...pile.querySelectorAll(":scope>.battle-mini-card")],first=cards[0],formation=pile.querySelector(".companion-formation"),lane=pile.closest('.battle-lane');if(!first||!formation||!lane)return;
      const laneStyle=getComputedStyle(lane),available=Math.max(memberWidth,lane.clientWidth-parseFloat(laneStyle.paddingLeft)-parseFloat(laneStyle.paddingRight));
      const members=formation.children.length,fit=Math.max(1,Math.floor((available-memberWidth)/step)+1),columns=Math.max(1,Math.min(6,members,fit)),rows=Math.max(1,Math.ceil(members/columns));
      const width=members?memberWidth+(columns-1)*step:0,height=members?memberHeight+(rows-1)*rowStep:0,lift=Math.min(9,(cards.length-1)*1.5);
      pile.style.setProperty('--stack-card-width',first.offsetWidth+'px');pile.style.setProperty('--formation-width',Math.max(first.offsetWidth+(cards.length-1)*2,width)+'px');pile.style.setProperty('--stack-lift',lift+'px');
      if(!pile.classList.contains('expanded'))pile.style.height=first.offsetHeight+'px';else pile.style.height='auto';
      formation.style.setProperty('--formation-cols',columns);formation.style.setProperty('--formation-step',step+'px');formation.style.setProperty('--formation-row-step',rowStep+'px');
      const headroom=pile.classList.contains('expanded')?0:Math.max(0,height+lift-first.offsetHeight/2+6);
      lane.style.setProperty('--formation-headroom',Math.max(parseFloat(lane.style.getPropertyValue('--formation-headroom'))||0,headroom)+'px');
    });
  }
  let hologramSyncFrame=0;function queueHologramSync(){if(hologramSyncFrame)return;hologramSyncFrame=requestAnimationFrame(()=>{hologramSyncFrame=0;syncBattleHolograms();});}
  window.addEventListener("resize",queueHologramSync);window.addEventListener("scroll",queueHologramSync,true);
  window.addEventListener("mythic-account-signed-out",()=>{
    duel=null;saveDuel();closeCardDetail();document.body.classList.remove("duel-fullscreen");
    document.getElementById("battle-hologram-layer")?.remove();
    document.getElementById("view-duel").hidden=true;
  });
  function newMatchUuid(){return window.crypto?.randomUUID?.()||"xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,char=>{const value=Math.random()*16|0;return (char==="x"?value:(value&3|8)).toString(16);});}
  function showMatchResult(){if(duel?.practice)return;if(!duel?.finished||duel.resultAnimationShown)return;if(duel.guardianCampaign&&duel.matchTiebreak&&window.MythicTieBreak){duel.resultAnimationShown=true;$("#match-result-banner").hidden=true;window.MythicTieBreak.openCampaign(duel.matchTiebreak);return;}const resultId=duel.onlineMatchId||(duel.localMatchId||(duel.localMatchId=newMatchUuid()));duel.finishedAt=duel.finishedAt||Date.now();completeTutorialAfterMatch();const banner=$("#match-result-banner"),title=$("#match-result-title"),loader=$("#duel-loading-screen"),caption=loader.querySelector(".loading-caption"),result=duel.serverOutcome?duel.serverOutcome:duel.roundWins.player>duel.roundWins.enemy?"victory":duel.roundWins.enemy>duel.roundWins.player?"defeat":"draw";banner.classList.remove("victory","defeat","draw");banner.classList.add(result);title.textContent=result==="victory"?"Vitória":result==="defeat"?"Derrota":"Empate";banner.hidden=false;duel.resultAnimationShown=true;if(result==="draw"&&window.MythicTieBreak){banner.hidden=true;$("#tie-break-panel").hidden=true;if(duel.online){window.MythicOnline?.loadTieBreak?.(duel.onlineMatchId);}else{const pool=duel.tieBreakDecks?.player||[...duel.player.hand,...duel.player.deck,...duel.player.underworld,...duel.player.field.map(u=>u.eclipseOriginalCardId||u.cardId)];window.MythicTieBreak.openGuardian({id:duel.localMatchId||(duel.localMatchId=newMatchUuid()),points:duel.roundWins.player,cards:pool});}return;}$("#tie-break-panel").hidden=!(duel.online&&duel.teamSize!==2&&result==="draw");if(duel.online){window.MythicOnline?.refreshProfile?.();if(result==="draw"&&duel.teamSize!==2){window.MythicOnline?.loadTieBreak?.(duel.onlineMatchId);return;}}else{const record={outcome:result,opponent_name:"Guardião da Arena",mode:"guardian",player_points:duel.roundWins.player,opponent_points:duel.roundWins.enemy,xp_earned:0,coins_earned:0,completed_at:new Date().toISOString()};try{const saved=JSON.parse(localStorage.getItem("mythic-clash-local-history:"+(window.MythicOnline?.userId?.()||"offline"))||"[]");localStorage.setItem("mythic-clash-local-history:"+(window.MythicOnline?.userId?.()||"offline"),JSON.stringify([record,...saved].slice(0,20)));}catch{}window.dispatchEvent(new CustomEvent("mythic-history-updated"));window.MythicOnline?.recordGuardianMatch?.(duel.localMatchId||(duel.localMatchId=newMatchUuid()),result,duel.roundWins.player,duel.roundWins.enemy);}setTimeout(()=>{if(activeView==="duel"&&!document.body.classList.contains("public-home-open")&&duel?.finished&&(duel.onlineMatchId||duel.localMatchId)===resultId)showCompletedReport();},3500);}
  window.MythicGame=window.MythicGame||{};
  let practiceDeck=null;
  function practiceBusy(){if(!duel?.practice)return true;if(duel.pendingEffect||window.MythicCombatFX?.isBusy()||window.MythicEclipseUI?.isRevealing()){showToast('Conclua a habilidade ou aguarde a animação.');return true;}return false;}
  function practiceReady(){if(!duel?.practice)return;duel.owner='player';for(const side of [duel.player,duel.enemy]){side.playedThisTurn=false;side.passed=false;}}
  function practiceSide(hand=[]){return {trixx:2,roundPenalty:0,turnsTaken:0,passed:false,playedThisTurn:false,deck:[],hand:[...hand],field:[],underworld:[],greekAura:0,norseAura:0};}
  function startPractice(restart=false){
    if(window.MythicAvailability?.checkDeck(window.MythicSelectedPracticeDeck?.()||deckCounts)===false)return;
    if(!window.MythicOnline?.isConnected?.()){window.MythicOnline?.showLogin?.();return;}
    if(!window.MythicOnline?.profileReady?.()){showToast('Aguarde sua coleção carregar.');return;}
    if(duel&&!duel.practice&&!duel.finished){showToast('Saia da partida atual antes de iniciar um teste.');return;}
    const selected=restart?practiceDeck:makeDeck(window.MythicSelectedPracticeDeck?.()||deckCounts);if(!selected?.length){showToast('Adicione cartas ao baralho para testar.');return;}practiceDeck=[...selected];
    window.MythicAbilitiesUI?.close();window.MythicCombatFX?.clear();window.MythicEclipseUI?.close();$('#card-detail-backdrop').hidden=true;pendingDrawAnimations.length=0;
    duel={practice:true,startedAt:Date.now(),matchStats:{plays:[],actions:0,passes:0},localMatchId:newMatchUuid(),rulesVersion:9,isTutorial:false,round:1,turn:1,owner:'player',opponentName:'Adversário de teste',sharedZones:{local:null,terrain:null,climate:null},zoneOwners:{},totalPoints:{player:0,enemy:0},roundWins:{player:0,enemy:0},player:practiceSide(selected),enemy:practiceSide(),log:['Teste iniciado. Todas as cartas do baralho estão na sua mão.'],finished:false};
    showView('duel');renderDuel();
  }
  function exitPractice(){if(!duel?.practice)return;duel.roundScores=duel.roundScores||[];if(!duel.roundScores.some(r=>r.round===duel.round))duel.roundScores.push({round:duel.round,player:roundScore(duel.player),enemy:roundScore(duel.enemy),in_progress:true});duel.finished=true;duel.finishedAt=Date.now();showCompletedReport();}
  function practiceNextTurn(){if(practiceBusy())return;const actor=duel.practiceTurnActor||'player';endAbilityTurn(actor);const next=actor==='player'?'enemy':'player';duel.practiceTurnActor=next;practiceReady();duel.turn++;duel[next].turnsTaken++;const ctx=abilitiesContext();window.MythicAbilities.turnStart(ctx,next);flushAbilities(ctx);duel[actor].skipNextTurn=false;log('Turno de teste avançado para '+(next==='player'?'você':'o adversário')+'. Uma jogada foi contada para os efeitos.');renderDuel();}
  function practiceNextRound(){if(practiceBusy())return;endAbilityTurn(duel.practiceTurnActor||'player');delete duel.practiceTurnActor;const ctx=abilitiesContext();window.MythicAbilities.roundEnd(ctx);flushAbilities(ctx);const one=roundScore(duel.player),two=roundScore(duel.enemy);duel.roundScores=duel.roundScores||[];duel.roundScores.push({round:duel.round,player:one,enemy:two});duel.roundWins.player+=one>two?1:0;duel.roundWins.enemy+=two>one?1:0;duel.totalPoints.player=one;duel.totalPoints.enemy=two;const clear=abilitiesContext();window.MythicAbilities.clearRound(clear);flushAbilities(clear);duel.round++;duel.roundSummary={winner:one>two?'player':two>one?'enemy':null};practiceReady();log(`Round de teste encerrado: ${one} × ${two}. Campo, Eclipse e efeitos foram limpos; as cartas foram para o Submundo.`);renderDuel();}
  function renderPracticeState(){const enabled=Boolean(duel?.practice&&!duel.finished);document.body.classList.toggle('practice-active',enabled);document.body.classList.toggle('practice-compact',enabled);const rule=document.querySelector('.hand-instruction');if(rule){rule.dataset.standardText=rule.dataset.standardText||rule.textContent;rule.textContent=enabled?'Teste livre: todas as cartas começam na mão. Use o laboratório para reservar compras, avançar turnos e montar situações.':rule.dataset.standardText;}window.MythicPracticeUI?.sync(enabled?{round:duel.round,enemy:duel.enemy.field.map(u=>({uid:u.uid,name:cardById[u.cardId]?.name,lane:u.lane})),handCount:duel.player.hand.length}:null);if(!enabled)return;$('#duel-mode-label').textContent='✦ MODO TESTE · COMBOS';$('#duel-mode-caption').textContent='Controle o cenário e experimente seu baralho.';$('#turn-label').textContent='TESTE LIVRE · ROUND '+duel.round;$('#turn-phase').textContent='Jogue suas cartas, configure o adversário e avance o turno quando quiser.';$('#end-turn').textContent='Avançar turno de teste';$('#end-turn').disabled=Boolean(duel.pendingEffect);}
  window.MythicPractice={start:()=>startPractice(),restart:()=>{if(!practiceBusy())startPractice(true);},nextRound:practiceNextRound,nextTurn:practiceNextTurn,
    addEnemy(id,lane){if(practiceBusy())return;const c=cardById[id];if(!c||c.kind!=='unit'||c.specialOnly||c.previewOnly)return;if(duel.enemy.field.length>=35){showToast('O campo de teste permite até 35 inimigos.');return;}try{const ctx=abilitiesContext();ctx.r.enemy.hand.push(id);ctx.r.enemy.passed=false;ctx.r.enemy.playedThisTurn=false;ctx.r.enemy.skipNextTurn=false;window.MythicAbilities.action(ctx,'enemy',{type:'play',card_id:id,lane:Number(lane)});flushAbilities(ctx);trackLocalAction('enemy',{type:'play',card_id:id});practiceReady();renderDuel();}catch(error){showToast(error.message);}},
    removeEnemy(id){if(practiceBusy())return;const ctx=abilitiesContext();window.MythicAbilities.destroyUnit(ctx,'player_two',id);flushAbilities(ctx);practiceReady();renderDuel();},
    reserveDraws(){if(practiceBusy())return;if(duel.player.hand.length<=4){showToast('Reponha as cartas para reservar compras.');return;}duel.player.deck.push(...duel.player.hand.splice(4));log('Quatro cartas ficaram na mão; as demais estão no baralho para testar compras e o topo.');renderDuel();},
    draw(){if(practiceBusy())return;draw(duel.player,1);practiceReady();renderDuel();},
    holdEnemy(id){if(practiceBusy())return;const c=cardById[id];if(!c||c.kind!=='unit'||c.specialOnly||c.previewOnly)return;if(duel.enemy.hand.length>=35){showToast('A mão de teste permite até 35 cartas.');return;}duel.enemy.hand.push(id);log(c.name+' foi adicionada à mão do adversário de teste.');renderDuel();},
    refill(){if(practiceBusy())return;const used=new Map();for(const id of duel.player.hand)used.set(id,(used.get(id)||0)+1);for(const id of practiceDeck){const n=used.get(id)||0;if(n)used.set(id,n-1);else duel.player.hand.push(id);}practiceReady();log('Cartas do baralho repostas na mão de teste.');renderDuel();},exit:()=>{if(duel?.practice)exitPractice();}
  };

  window.MythicGame.refreshBattle=()=>{if(duel&&activeView==="duel")renderDuel();};
