 async function loadJourney(){if(window.MythicGuardianCampaign||!connected)return;const token=window.MythicOnline.userId();try{const data=await rpc('get_guardian_journey');if(token!==window.MythicOnline.userId())return;guardian.querySelectorAll('.guardian-server-mission').forEach(n=>n.remove());for(const m of data.missions||[]){const article=el('article','panel guardian-mission guardian-server-mission');article.append(el('small','',m.claimed?'CONCLUÍDA':'MISSÃO'),el('h2','',m.title),el('p','',m.description),el('p','',`${Math.min(m.progress,m.target_count)} / ${m.target_count} · ${m.reward_xp} XP · ${m.reward_coins} MC`));const action=btn(m.claimed?'Recompensa recebida':m.progress>=m.target_count?'Resgatar recompensa':'Jogar missão',async()=>{if(m.progress<m.target_count){guardianStart();return;}action.disabled=true;try{await rpc('claim_mission',{p_mission_id:m.mission_id});await window.MythicOnline.refreshProfile();await loadJourney();}catch(e){guardian.querySelector('.guardian-status').textContent=e.message;action.disabled=false;}},'button button-primary');action.disabled=Boolean(m.claimed);article.append(action);guardian.querySelector('.guardian-missions').append(article);}guardian.querySelector('.guardian-status').textContent=data.tutorial_completed?'Treinamento inicial concluído. Continue aprimorando seus combos.':'Seu primeiro desafio inclui as instruções de combate.';}catch(e){guardian.querySelector('.guardian-status').textContent=e.message;}}
