 for(const tab of admin.querySelectorAll('[data-admin-tab]'))tab.addEventListener('click',()=>{admin.querySelectorAll('[data-admin-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===tab)));admin.querySelectorAll('[data-admin-section]').forEach(s=>s.hidden=s.dataset.adminSection!==tab.dataset.adminTab);if(tab.dataset.adminTab==='metrics')metrics();if(tab.dataset.adminTab==='cards')availabilityList();if(tab.dataset.adminTab==='users')loadUsers();if(tab.dataset.adminTab==='roles')loadRoles();});
