/* practice-mode.js */
(() => {
 'use strict';
 const make=(tag,text,cls)=>{const node=document.createElement(tag);if(text)node.textContent=text;if(cls)node.className=cls;return node;};
 const button=(text,fn)=>{const node=make('button',text,'button button-secondary');node.type='button';node.addEventListener('click',fn);return node;};
 const entry=button('⚔ Testar baralho',()=>window.MythicPractice?.start());entry.id='practice-start';entry.classList.add('practice-start');document.querySelector('#view-decks .page-heading').append(entry);
 const open=button('⚙ Configurar teste',()=>{paintCards();dialog.showModal();});open.id='practice-controls-open';open.hidden=true;document.body.append(open);
 const dialog=make('dialog',null,'practice-dialog');dialog.setAttribute('aria-labelledby','practice-title');const header=make('header');const title=make('h2','Laboratório de combos');title.id='practice-title';header.append(title,button('Fechar',()=>dialog.close()));dialog.append(header,make('p','Escolha os personagens do adversário e a fileira. As habilidades são ativadas normalmente; você decide todos os alvos dos dois lados.'));
 const search=make('input');search.type='search';search.placeholder='Buscar personagem inimigo…';search.setAttribute('aria-label','Buscar personagem inimigo');
 const select=make('select');select.setAttribute('aria-label','Personagem inimigo');const lane=make('select');lane.setAttribute('aria-label','Fileira do inimigo');for(let n=0;n<3;n++)lane.append(new Option('Fileira '+(n+1),String(n)));
 const preview=make('img');preview.className='practice-card-preview';preview.alt='Carta selecionada';preview.hidden=true;
 const status=make('p');status.setAttribute('role','status');status.className='practice-status';
 const row=make('div',null,'practice-enemy-controls');row.append(search,select,lane,button('Adicionar à mão inimiga',()=>{if(!select.value)return;dialog.close();window.MythicPractice.holdEnemy(select.value);}),button('Invocar inimigo',()=>{if(!select.value)return;dialog.close();window.MythicPractice.addEnemy(select.value,lane.value);}));dialog.append(row,preview);
 const remove=make('select');remove.setAttribute('aria-label','Inimigo em campo para enviar ao Submundo');const removal=make('div',null,'practice-actions');removal.append(remove,button('Enviar ao Submundo',()=>{if(!remove.value)return;dialog.close();window.MythicPractice.removeEnemy(remove.value);}));dialog.append(removal);
 const actions=make('div',null,'practice-actions');for(const [text,method] of [['Repor cartas na mão','refill'],['Reservar compras no baralho','reserveDraws'],['Comprar uma carta','draw'],['Avançar turno','nextTurn'],['Encerrar Round','nextRound'],['Reiniciar teste','restart'],['Voltar aos baralhos','exit']])actions.append(button(text,()=>{dialog.close();window.MythicPractice[method]();}));dialog.append(actions,status,make('small','Teste livre: sem cronômetro, moedas, XP ou alteração do baralho salvo. “Repor cartas” cria novas cópias apenas nesta simulação.'));document.body.append(dialog);
 function cards(){return (window.MythicCardData?.()||[]).filter(c=>c.kind==='unit'&&!c.specialOnly&&!c.previewOnly);}
 function paintPreview(){const card=cards().find(c=>c.id===select.value);preview.hidden=!card?.art;if(card?.art){preview.src=window.MythicSecurity.assetUrl(card.art);preview.alt=card.name;}}
 function paintCards(){const previous=select.value,q=search.value.trim().toLocaleLowerCase('pt-BR');select.replaceChildren();for(const c of cards().filter(c=>c.name.toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')))select.append(new Option(c.name+' · '+c.power+' poder',c.id));if([...select.options].some(o=>o.value===previous))select.value=previous;paintPreview();}
 search.addEventListener('input',paintCards);select.addEventListener('change',paintPreview);
 window.MythicPracticeUI={sync(state){open.hidden=!state;if(!state){if(dialog.open)dialog.close();return;}const previous=remove.value;remove.replaceChildren();for(const unit of state.enemy)remove.append(new Option(unit.name+' · Fileira '+(unit.lane+1),unit.uid));if([...remove.options].some(o=>o.value===previous))remove.value=previous;status.textContent=`Round ${state.round} · ${state.handCount} cartas na sua mão · ${state.enemy.length} inimigos em campo`;}};
})();

