 function ensure(){if(toolbar)return;toolbar=el('section','shop-filters');toolbar.setAttribute('aria-label','Classificar itens da loja');for(const [key,title,kind]of [['query','Buscar','search'],['faction','Facção','select'],['type','Tipo','select'],['owned','Coleção','select'],['sort','Ordenar','select']]){const label=el('label','',title),control=el(kind==='select'?'select':'input');control.dataset.filter=key;control.setAttribute('aria-label',title+' na loja');if(kind==='search'){control.type='search';control.placeholder='Nome, personagem ou habilidade';control.maxLength=80;}label.append(control);toolbar.append(label);control.addEventListener(kind==='search'?'input':'change',()=>{state[key]=control.value;save();window.MythicOnline.repaintStore();});}const count=el('p','shop-filter-count');count.setAttribute('role','status');toolbar.append(count);$('#store-product-area').prepend(toolbar);}
