 function paint(){card.hidden=!enabled;resume.hidden=enabled||!pendingMatch;grid?.classList.toggle('has-solo-tiebreak',enabled);setting.checked=enabled;admin.hidden=!api().isAdmin();card.querySelector('small').textContent=pendingMatch?'Há uma puxada online pronta para revelar.':'Encontre outro jogador e deixe as cartas decidirem.';}
 function close(){clearTimeout(timer);timer=null;modal?.close();modal?.remove();modal=null;status=null;select=null;start=null;cancel=null;waiting=false;}
